CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('admin','editor','sales','manager','hr','customer')), password TEXT, active INTEGER NOT NULL DEFAULT 1, verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE auth_tokens(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL CHECK(purpose IN ('invite','reset')),expires INTEGER NOT NULL);
CREATE TABLE inquiries(id TEXT PRIMARY KEY,number TEXT UNIQUE NOT NULL,owner TEXT REFERENCES users(id),assignee TEXT REFERENCES users(id), status TEXT NOT NULL DEFAULT 'received',data TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notes(id INTEGER PRIMARY KEY,inquiry_id TEXT NOT NULL REFERENCES inquiries(id) ON DELETE CASCADE,author TEXT REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,status TEXT NOT NULL,inquiry_id TEXT REFERENCES inquiries(id),description TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE applications(id TEXT PRIMARY KEY,number TEXT UNIQUE NOT NULL,job TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'received',data TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE files(id TEXT PRIMARY KEY,inquiry_id TEXT REFERENCES inquiries(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,application_id TEXT REFERENCES applications(id) ON DELETE CASCADE,name TEXT NOT NULL,mime TEXT NOT NULL,body BLOB NOT NULL,version INTEGER NOT NULL,author TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK((inquiry_id IS NOT NULL)+(project_id IS NOT NULL)+(application_id IS NOT NULL)=1));
CREATE TABLE messages(id INTEGER PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,author TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE content(kind TEXT NOT NULL,slug TEXT NOT NULL,draft TEXT NOT NULL,published TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(kind,slug));
CREATE TABLE revisions(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,slug TEXT NOT NULL,content TEXT NOT NULL,action TEXT NOT NULL,author TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(kind,slug) REFERENCES content(kind,slug));
CREATE TABLE media(id TEXT PRIMARY KEY,name TEXT NOT NULL,mime TEXT NOT NULL,body BLOB NOT NULL,credit TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY,actor TEXT,event TEXT NOT NULL,object TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE outbox(id INTEGER PRIMARY KEY,recipient TEXT,kind TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE INDEX inquiry_owner ON inquiries(owner);
CREATE INDEX project_owner ON projects(owner);
CREATE INDEX messages_project ON messages(project_id,id);
CREATE INDEX files_project ON files(project_id,name,version);
CREATE INDEX revisions_entry ON revisions(kind,slug,id);
CREATE INDEX applications_created ON applications(created_at);
